import type { JsonValue } from './capabilities.js';
import type { SessionRef } from './identity.js';
export type HistoryFence = Readonly<{ id: string; sourceGeneration: string | number }>;
export type HistoryCapabilities = Readonly<{ archive: 'paged' | 'live-only' | 'unsupported'; recordStream: boolean; live: 'invalidate' | 'unsupported' }>;
export type HistoryOpenParams = Readonly<{ historyId: string; session: SessionRef; agentId?: string }>;
export type HistoryOpenResult = Readonly<{ historyId: string; session: SessionRef; fence: HistoryFence; capabilities: HistoryCapabilities; reason?: string }>;
export type HistoryPageParams = Readonly<{ historyId: string; cursor?: string; releasePageIds?: readonly string[] }>;
export type HistoryDescriptor = Readonly<{ id: string; format: 'native-json-utf8'; totalBytes: number; sha256: string; preview?: string }>;
export type HistoryItem = Readonly<{ recordId: string; kind: 'inline'; value: JsonValue }> | Readonly<{ recordId: string; kind: 'stream'; descriptor: HistoryDescriptor }>;
export type HistoryPage = Readonly<{ historyId: string; session: SessionRef; fence: HistoryFence; pageId: string; items: readonly HistoryItem[]; document?: HistoryDescriptor; cursor: string | null; completeness: 'complete' | 'partial' | 'unsupported'; reason?: string }>;
export type HistoryChunkParams = Readonly<{ historyId: string; pageId: string; descriptorId: string; offset: number }>;
export type HistoryChunk = Readonly<{ historyId: string; fence: HistoryFence; pageId: string; descriptorId: string; offset: number; totalBytes: number; sha256: string; data: string; nextOffset: number | null }>;
export type HistoryReadParams = Readonly<{ historyId: string; after: number }>;
export type HistoryChange = Readonly<{ historyId: string; fence: HistoryFence; through: number; changed: boolean; status: 'current' | 'replay_required' | 'source_unavailable'; reason?: string }>;
export type HistoryCloseParams = Readonly<{ historyId: string }>;
export const HISTORY_LIMITS: Readonly<{ recordsPerPage: 200; logicalInlineBytesPerPage: 2097152; encodedResultBytes: 524288; decodedChunkBytes: 65536; selectedPages: 3; clientResidentAndPendingBytes: 16777216; inlineBytes: 32768; nodes: 4096; depth: 16; readTimeoutMs: 10000; tombstones: 1024 }>;
export function parseHistoryOpen(value: unknown): HistoryOpenResult;
export function parseHistoryPage(value: unknown): HistoryPage;
export function parseHistoryChunk(value: unknown): HistoryChunk;
export function parseHistoryChange(value: unknown): HistoryChange;
